const item = $input.item.json;
let url = item.external_url;
if (!url) {
  return { json: { ...item, url: null, fetched_ok: false } };
}
// Ensure it has scheme
if (!url.startsWith('http')) url = 'https://' + url;
return { json: { ...item, url } };

const item = $input.item.json;
const prev = $('Fetch Job Record').item.json;

let pageText = '';
if (typeof item.data === 'string') {
  pageText = item.data
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 12000);
}

return {
  json: {
    ...prev,
    page_text: pageText,
    fetched_ok: pageText.length > 200
  }
};

const item = $input.item.json;

const prompt = `You are a senior recruitment business development analyst at Torren Technical, an engineer-led Australian technical recruitment firm. You have a job posting (quick score ${item.ai_score}/15, ${item.score_band}, entity_type=${item.entity_type}). Your job: produce decision-grade commercial intelligence so a recruiter can pick up the phone within minutes.

RETURN ONLY valid JSON. No markdown. Exact structure:

{
  "full_description": "2-4 sentences on the role in your own words",
  "key_requirements": ["concise", "must-haves"],
  "nice_to_haves": ["concise", "preferreds"],
  "company_blurb": "1-2 sentences on what the company does, or null if unclear",
  "company_size_hint": "SME | mid-size | large | agency | unknown",
  "hiring_contact_name": "name if explicitly stated, else null",
  "hiring_contact_email": "email if explicitly stated, else null",
  "fifo": "yes | no | unclear",
  "contract_type": "permanent | contract | casual | fixed-term | unclear",
  "salary_clarified": "best salary string available",
  "salary_min": null,
  "salary_max": null,
  "inferred_client_name": null,
  "inferred_client_confidence": 1,
  "pain_hypothesis": "1 sentence: what problem is the lister trying to solve by hiring this role",
  "outreach_angle": "1 sentence: how a Torren Technical recruiter could open a relevant conversation",
  "recommended_service": "retainer_search | per_shortlist_search | contingent_recruitment | recruiter_sourcing_support | do_not_pursue",
  "recommended_first_action": "the single most useful first action a recruiter should take",
  "employee_instruction": "specific call script opener for the recruiter",
  "relationship_potential": 1,
  "placement_probability": 1,
  "commercial_viability": 1,
  "additional_flags": []
}

CONTEXT FROM EARLIER SCORING:
Role: ${item.role_title}
Company: ${item.company_name}
Location: ${[item.location_city, item.location_state].filter(Boolean).join(', ')}
Source: ${item.external_source}
Salary text: ${item.salary_text || 'unknown'}
Quick score reasoning: ${item.ai_score_reasoning || 'none'}

JOB PAGE TEXT (may be empty or partial):
${item.page_text || 'No fresh page text available - rely on context above.'}`;

return [{
  json: {
    ...item,
    de_model: 'claude-haiku-4-5',
    de_max_tokens: 2048,
    de_prompt: prompt
  }
}];

const response = $input.item.json;
const upstream = $('Fetch Job Record').item.json;
const content = response.content?.[0]?.text || '';

let extracted = {};
try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  extracted = JSON.parse(cleaned);
} catch (e) {
  extracted = { error: 'parse failed' };
}

function clampInt(v, min, max) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseInt(v);
  if (isNaN(n)) return null;
  return Math.min(max, Math.max(min, n));
}

function intOrNull(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseInt(v);
  return isNaN(n) ? null : n;
}

return {
  json: {
    job_id: upstream.id,
    pain_hypothesis: extracted.pain_hypothesis || null,
    outreach_angle: extracted.outreach_angle || null,
    entity_type: upstream.entity_type,  // keep existing — don't downgrade
    recommended_service: extracted.recommended_service || 'unknown',
    recommended_first_action: extracted.recommended_first_action || null,
    employee_instruction: extracted.employee_instruction || null,
    inferred_client_name: extracted.inferred_client_name || null,
    inferred_client_confidence: clampInt(extracted.inferred_client_confidence, 1, 5),
    relationship_potential: clampInt(extracted.relationship_potential, 1, 5),
    placement_probability: clampInt(extracted.placement_probability, 1, 5),
    commercial_viability: clampInt(extracted.commercial_viability, 1, 5),
    salary_min: intOrNull(extracted.salary_min),
    salary_max: intOrNull(extracted.salary_max),
    salary_clarified: extracted.salary_clarified || null
  }
};
